import {projects,press,biography,exhibition} from './portfolio-data.js';
import {createWorld} from './world.js';
import {galleryMarkup,mountGallery} from './portfolio-gallery.js';
const $=s=>document.querySelector(s);
const escape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const main=$('#main');
const world=createWorld($('#gallery-world'),id=>{const work=exhibition.find(x=>x.id===id);if(work)location.hash=`#serie/${work.project}`;});
let dispose=()=>{},galleryPosition=0,filter='Tout',viewImages=[],viewTitle='',photoIndex=0,returnFocus=null;
const image=(photo,title,priority=false)=>`<img src="${escape(photo.file)}" alt="${escape(title)}" width="${photo.width}" height="${photo.height}" ${priority?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
const link=(href,text,active=false)=>`<a href="${href}" ${active?'aria-current="page"':''}>${text}</a>`;
function header(route){
 $('#header').innerHTML=`<div class="site-header"><a class="wordmark" href="#galerie" aria-label="Antoine Martin, accueil">Antoine Martin<span>Photographe</span></a><nav aria-label="Navigation principale">${link('#galerie','La galerie',route==='galerie')}${link('#series','Les séries',route==='series'||route==='serie')}${link('#publications','Publications',route==='publications'||route==='publication')}${link('#a-propos','À propos',route==='a-propos')}${link('#contact','Contact',route==='contact')}</nav><details class="mobile-menu"><summary>Menu</summary><nav aria-label="Navigation mobile">${link('#galerie','La galerie')}${link('#series','Les séries')}${link('#publications','Publications')}${link('#a-propos','À propos')}${link('#contact','Contact')}</nav></details></div>`;
}
function footer(){
 $('#footer').innerHTML=`<div class="footer-top"><p>Un projet, une commande,<br>une conversation.</p><a href="mailto:contact@martinantoine.com">contact@martinantoine.com</a></div><div class="footer-bottom"><span>Photographies © Antoine Martin</span><a href="https://www.instagram.com/antoinemartiin/" target="_blank" rel="noopener noreferrer">Instagram</a><a href="#credits">Crédits & sources</a><span>Étude de portfolio · 2026</span></div>`;
}
function home(){main.innerHTML=galleryMarkup(exhibition);world.show(exhibition,exhibition[0].id,'visit');dispose=mountGallery($('.gallery-story'),exhibition,{initialProgress:galleryPosition,onPosition:p=>galleryPosition=p,world});}
function projectCard(p,i){return `<article class="project-card"><a href="#serie/${p.id}"><div class="project-image">${image(p.images[p.cover],`${p.title}, photographie d’Antoine Martin`,i<2)}<span class="image-action">Voir la série</span></div><div class="project-caption"><h2>${escape(p.title)}</h2><p>${escape(p.place)}<span>${escape(p.period)}</span></p></div></a></article>`;}
function series(){
 main.innerHTML=`<section class="page-heading"><p class="eyebrow">Travaux photographiques</p><div><h1>Les séries<span class="serif-dot">.</span></h1><p>Des lieux où l’on revient.<br>Des histoires que l’on prend le temps de regarder.</p></div></section><div class="filters" role="group" aria-label="Filtrer les séries">${['Tout','Séries personnelles','Commandes','Commercial','Archives'].map(x=>`<button type="button" data-filter="${x}" aria-pressed="${x===filter}">${x}</button>`).join('')}<span id="result-count" role="status"></span></div><section class="projects-grid" aria-label="Séries photographiques" id="projects-grid"></section>`;updateProjects();
}
function updateProjects(){const list=projects.filter(p=>filter==='Tout'?p.category!=='Archives':p.category===filter);$('#projects-grid').innerHTML=list.map(projectCard).join('');$('#result-count').textContent=`${list.length} séries`;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));}
function photoGrid(images,title){return `<div class="photo-grid">${images.map((x,i)=>`<figure class="photo-item ${x.height>x.width?'portrait':''}"><button type="button" data-photo="${i}" aria-label="Ouvrir la photographie ${i+1} de ${escape(title)}">${image(x,`${title}, photographie ${i+1} d’Antoine Martin`,i<2)}</button></figure>`).join('')}</div>`;}
function detail(id){
 const p=projects.find(p=>p.id===id);if(!p)return notFound();viewImages=p.images;viewTitle=p.title;
 const others=projects.filter(x=>x.category===p.category),next=others[(others.indexOf(p)+1)%others.length];
 main.innerHTML=`<section class="series-heading"><a class="back-link" href="#series">Toutes les séries</a><div class="series-heading-grid"><div><p class="eyebrow">${escape(p.category)} · ${escape(p.place)}</p><h1>${escape(p.title)}</h1><p class="series-subtitle">${escape(p.subtitle)}</p></div><div class="series-context"><p class="series-period">${escape(p.period)}</p>${p.paragraphs.map(t=>`<p>${escape(t)}</p>`).join('')}<p class="photo-credit">${p.images.length} photographies · © Antoine Martin</p></div></div></section>${photoGrid(p.images,p.title)}<section class="series-end"><span>Continuer à regarder</span><a href="#serie/${next.id}">${escape(next.title)}</a><a class="text-link" href="#series">Retour aux séries</a></section>`;document.title=`${p.title} | Antoine Martin`;
}
function publications(){main.innerHTML=`<section class="page-heading"><p class="eyebrow">Dans les pages</p><div><h1>Publications<span class="serif-dot">.</span></h1><p>Les photographies poursuivent<br>leur vie dans la presse.</p></div></section><section class="press-list" aria-label="Publications">${press.map(p=>`<a class="press-row" href="#publication/${p.id}"><div>${image(p.images[0],p.title)}</div><h2>${escape(p.title)}</h2><span>Feuilleter</span></a>`).join('')}</section>`;}
function publication(id){const p=press.find(p=>p.id===id);if(!p)return notFound();viewImages=p.images;viewTitle=p.title;main.innerHTML=`<section class="page-heading"><a href="#publications" class="back-link">Toutes les publications</a><div><h1>${escape(p.title)}</h1><p>Parutions et pages publiées${p.links.length?`<br><a class="text-link" href="${escape(p.links[0])}" target="_blank" rel="noopener noreferrer">Lire sur le site du magazine</a>`:''}</p></div></section>${photoGrid(p.images,p.title)}`;document.title=`${p.title} | Antoine Martin`;}
function about(){main.innerHTML=`<section class="about-heading"><p class="eyebrow">Antoine Martin · Photographe</p><h1>Prendre le temps<br>de <em>revenir.</em></h1></section><section class="about-grid"><p class="about-intro">Entre documentaire<br>et journalisme.</p><div class="about-copy">${biography.map(p=>`<p>${escape(p)}</p>`).join('')}<a class="text-link" href="#contact">Entrer en contact</a></div></section><div class="about-image">${image(projects[0].images[18],'Miami, not the Beach, Antoine Martin')}<p>Miami, not the Beach · 2018 · 2025</p></div><section class="recognition"><h2>Quelques repères</h2><div><h3>Prix</h3><p>2024 · Prix UPP</p><p>2024 · Prix Herez Corpo, choix du jury</p><p>2024 · Concours national de photographie Peleyre</p><p>2019 · Grand Prix du Photoreportage Paris Match étudiant, prix du public</p><h3>Expositions & projections</h3><p>2026 · Rotterdam Photo</p><p>2025 · Rencontres d’Arles, Miami, not the Beach</p><p>2025 · Galerie de l’UPP, Paris</p><p>2024 · Recherche sans filtre, Sorbonne Université</p></div></section>`;}
function contact(){main.innerHTML=`<section class="contact-page"><p class="eyebrow">Contact</p><h1>Parlons<br><em>images.</em></h1><div class="contact-grid"><p>Pour une commande, un reportage<br>ou une proposition d’exposition.<br><span>Disponible pour des projets à l’international.</span></p><div><a class="contact-email" href="mailto:contact@martinantoine.com">contact@martinantoine.com</a><a href="tel:+33666122832">+33 (0)6 66 12 28 32</a><a href="https://wa.me/33666122832" target="_blank" rel="noopener noreferrer">WhatsApp</a><a href="https://www.instagram.com/antoinemartiin/" target="_blank" rel="noopener noreferrer">Instagram · @antoinemartiin</a></div></div></section>`;}
function credits(){main.innerHTML=`<section class="page-heading"><p class="eyebrow">Crédits & sources</p><div><h1>Les images,<br>leur auteur.</h1><p>Photographies © Antoine Martin.<br>Étude de portfolio réalisée à partir de son site public, consulté le 23 novembre 2026.</p></div></section><section class="credits-copy"><p>Les titres des projets, leurs contextes et les coordonnées proviennent de <a href="https://www.martinantoine.com/" target="_blank" rel="noopener noreferrer">martinantoine.com</a>. Les textes français sont des adaptations et des textes de présentation. Les photographies conservent leurs proportions et l’ordre du site d’origine dans chaque série. L’accrochage de la galerie est une sélection éditoriale.</p><p>Cette proposition est une étude de site et ne constitue pas le site officiel d’Antoine Martin.</p><h2>Pages sources</h2><ul>${[...projects,...press].map(p=>`<li><a href="${p.source}" target="_blank" rel="noopener noreferrer">${escape(p.title)}</a></li>`).join('')}<li><a href="https://www.martinantoine.com/infos">Biographie et contact</a></li></ul><h2>Conception</h2><p>Galerie adaptée de PITTURA. Rendu 3D : Three.js (licence MIT). Typographies : Jost et Newsreader (licences SIL Open Font License).</p></section>`;}
function notFound(){main.innerHTML='<section class="page-heading"><h1>Cette page<br>n’existe pas.</h1><a class="text-link" href="#series">Découvrir les séries</a></section>';}
function render(){dispose();dispose=()=>{};world.stopVisit();if($('#lightbox').open)$('#lightbox').close();const [route='galerie',rawId='']=location.hash.slice(1).split('/');let id='';try{id=decodeURIComponent(rawId);}catch{}const isHome=route===''||route==='galerie';document.body.classList.toggle('is-gallery',isHome);document.body.classList.toggle('is-reading',!isHome);header(isHome?'galerie':route);footer();document.title='Antoine Martin | Photographe';window.scrollTo({top:0,behavior:'instant'});if(isHome)home();else if(route==='series')series();else if(route==='serie')detail(id);else if(route==='publications')publications();else if(route==='publication')publication(id);else if(route==='a-propos')about();else if(route==='contact')contact();else if(route==='credits')credits();else notFound();if(!isHome)main.focus({preventScroll:true});}
function showPhoto(index){photoIndex=Math.max(0,Math.min(viewImages.length-1,index));const photo=viewImages[photoIndex],dialog=$('#lightbox');dialog.classList.remove('zoomed');$('#lightbox-zoom').setAttribute('aria-pressed','false');$('#lightbox-zoom').textContent='Agrandir';const img=dialog.querySelector('img');img.src=photo.file;img.alt=`${viewTitle}, photographie ${photoIndex+1} d’Antoine Martin`;$('#lightbox-caption').textContent=viewTitle;$('#lightbox-count').textContent=`${photoIndex+1} / ${viewImages.length} · © Antoine Martin`;$('#lightbox-prev').disabled=photoIndex===0;$('#lightbox-next').disabled=photoIndex===viewImages.length-1;if(!dialog.open){returnFocus=document.activeElement;dialog.showModal();document.body.classList.add('dialog-open');}}
 document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.hasAttribute('data-filter')){filter=button.dataset.filter;updateProjects();}if(button.hasAttribute('data-photo'))showPhoto(Number(button.dataset.photo));});
$('#lightbox-close').addEventListener('click',()=>$('#lightbox').close());$('#lightbox').addEventListener('close',()=>{document.body.classList.remove('dialog-open');returnFocus?.isConnected&&returnFocus.focus({preventScroll:true});});$('#lightbox-prev').addEventListener('click',()=>showPhoto(photoIndex-1));$('#lightbox-next').addEventListener('click',()=>showPhoto(photoIndex+1));$('#lightbox-zoom').addEventListener('click',()=>{const zoomed=$('#lightbox').classList.toggle('zoomed');$('#lightbox-zoom').setAttribute('aria-pressed',String(zoomed));$('#lightbox-zoom').textContent=zoomed?'Vue entière':'Agrandir';});$('#lightbox').addEventListener('keydown',event=>{if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();showPhoto(photoIndex+(event.key==='ArrowRight'?1:-1));}});$('.skip').addEventListener('click',event=>{event.preventDefault();main.focus();});window.addEventListener('hashchange',render);
// Prime the existing gallery engine even when the first URL opens a series.
world.show(exhibition,exhibition[0].id,'visit');render();
